(window.SLIDES = window.SLIDES || []).push(

  // ───────── BIP ─────────
  { id: "vma-001", cat: "vwl", topic: "BIP", type: "fact", emoji: "🏭", level: 1,
    title: "BIP = Marktwert aller Endprodukte eines Jahres",
    text: "Das **Bruttoinlandsprodukt** misst den Wert aller Waren und Dienstleistungen, die in einem Jahr im Inland für die Endverwendung hergestellt werden. Vorleistungen (z. B. Stahl im Auto) zählen nicht extra – sonst würde doppelt gezählt.",
    more: "**Inlandsprinzip:** Auch das Werk eines japanischen Konzerns in Deutschland zählt zum deutschen BIP. Das Bruttonationaleinkommen (BNE) folgt dagegen dem Inländerprinzip: Es zählt die Einkommen der Inländer – egal, wo sie entstehen." },
  { id: "vma-002", cat: "vwl", topic: "BIP", type: "flashcard", emoji: "🔺", level: 2,
    term: "Die drei Seiten des BIP",
    def: "**Entstehung:** Wer produziert? (Sektoren) · **Verwendung:** Wofür? (Konsum, Investitionen, Staat, Außenbeitrag) · **Verteilung:** Wer erhält das Einkommen? (Arbeitnehmerentgelte vs. Unternehmens- und Vermögenseinkommen)",
    example: "Alle drei Rechnungen führen theoretisch zum selben Ergebnis – sie betrachten denselben Kuchen von drei Seiten." },
  { id: "vma-003", cat: "vwl", topic: "BIP", type: "quiz", emoji: "🛒", level: 1,
    q: "Verwendungsrechnung: BIP = C + I + G + (X − M). Welche Komponente ist in Deutschland die größte?",
    options: ["Staatskonsum (G)", "Private Konsumausgaben (C)", "Bruttoinvestitionen (I)", "Außenbeitrag (X − M)"],
    answer: 1,
    explain: "Der private Konsum macht gut die Hälfte des BIP aus. Darum ist Kaufzurückhaltung der Haushalte so gefährlich für die Konjunktur – auch in einer „Exportnation“." },
  { id: "vma-004", cat: "vwl", topic: "BIP", type: "truefalse", emoji: "📏", level: 1,
    q: "Steigt das nominale BIP um 5 %, ist die Wirtschaft um 5 % gewachsen.",
    answer: false,
    explain: "Das nominale BIP enthält Preissteigerungen. Bei 5 % nominal und 4 % Preisanstieg bleibt real nur rund 1 % Wachstum. Für echtes Wachstum zählt das **reale BIP** (in Preisen eines Basisjahres)." },
  { id: "vma-005", cat: "vwl", topic: "BIP", type: "flashcard", emoji: "🧮", level: 2,
    term: "BIP-Deflator",
    def: "Preisindex aller im Inland produzierten Güter: nominales BIP ÷ reales BIP × 100. Er zeigt, wie stark die Preise der eigenen Produktion gestiegen sind.",
    example: "Anders als der Verbraucherpreisindex enthält er auch Investitionsgüter und Exporte – aber keine Importe wie importiertes Öl." },
  { id: "vma-006", cat: "vwl", topic: "BIP", type: "quiz", emoji: "👶", level: 2,
    q: "Welche Tätigkeit erhöht das BIP NICHT?",
    options: ["Ein Handwerker renoviert ein Bad gegen Rechnung", "Der Staat bezahlt Lehrkräfte", "Eltern betreuen ihr Kind selbst zu Hause", "Ein Unternehmen kauft eine neue Maschine"],
    answer: 2,
    explain: "Unbezahlte Haus- und Pflegearbeit wird nicht erfasst. Paradox: Geht das Kind in eine bezahlte Kita, steigt das BIP – obwohl die Betreuung dieselbe bleibt." },
  { id: "vma-007", cat: "vwl", topic: "BIP", type: "fact", emoji: "⚠️", level: 2,
    title: "Das BIP misst Aktivität, nicht Wohlstand",
    text: "Unfälle, Reparaturen nach Fluten oder das Beseitigen von Umweltschäden erhöhen das BIP. Nicht erfasst werden Freizeit, Hausarbeit, die Verteilung der Einkommen und der Verbrauch von Natur.",
    more: "Alternativen: **Human Development Index** (Einkommen, Bildung, Lebenserwartung) oder der **Better Life Index** der OECD. Robert F. Kennedy 1968: Das BIP misst alles – außer dem, was das Leben lebenswert macht." },
  { id: "vma-008", cat: "vwl", topic: "BIP", type: "truefalse", emoji: "🕶️", level: 2,
    q: "Schwarzarbeit und illegale Geschäfte werden bei der BIP-Berechnung komplett ignoriert.",
    answer: false,
    explain: "Statistikämter schätzen Teile der Schattenwirtschaft ein. Seit der EU-weiten Umstellung 2014 (ESVG 2010) werden sogar illegale Märkte wie Drogenhandel geschätzt und einbezogen – damit die BIP-Zahlen der EU-Staaten vergleichbar sind." },
  { id: "vma-009", cat: "vwl", topic: "BIP", type: "quiz", emoji: "🇱🇺", level: 3,
    q: "Warum hat Luxemburg das mit Abstand höchste BIP pro Kopf der EU?",
    options: ["Viele Grenzpendler erarbeiten BIP, zählen aber nicht als Einwohner", "Große Ölvorkommen", "Besonders hohe Inflation", "Das BIP wird dort in Dollar gerechnet"],
    answer: 0,
    explain: "Fast die Hälfte der Beschäftigten pendelt aus Frankreich, Belgien und Deutschland ein. Ihre Produktion zählt zum Luxemburger BIP, sie selbst aber nicht zur Bevölkerung. Das BNE pro Kopf ist deshalb deutlich niedriger – ein Grund, BIP-Kennzahlen kritisch zu lesen." },
  { id: "vma-010", cat: "vwl", topic: "BIP", type: "whatif", emoji: "🌊", level: 2,
    q: "Was passiert mit dem BIP, wenn eine Flut Häuser und Straßen zerstört?",
    steps: ["Vermögen (Häuser, Straßen) wird vernichtet", "Kurzfristig fällt Produktion aus", "Wiederaufbau: Bauaufträge boomen", "Das BIP steigt teils sogar", "Der Wohlstand ist trotzdem gesunken"],
    text: "Das BIP ist eine **Stromgröße** (Produktion pro Jahr), kein Bestandsmaß. Die Zerstörung des Kapitalstocks taucht nicht auf, der Wiederaufbau schon. Frédéric Bastiat nannte den Denkfehler „Parabel vom zerbrochenen Fenster“: Das Geld für die Reparatur fehlt anderswo." },

  // ───────── Wachstum ─────────
  { id: "vma-011", cat: "vwl", topic: "Wachstum", type: "fact", emoji: "🌱", level: 1,
    title: "Wachstum hat drei Quellen",
    text: "Mehr **Arbeit** (Erwerbstätige, Stunden), mehr **Kapital** (Maschinen, Infrastruktur) und höhere **Produktivität** durch technischen Fortschritt und bessere Organisation. Langfristig entscheidet die Produktivität.",
    more: "Solow-Modell: Immer mehr Maschinen bringen abnehmende Zusatzerträge – ohne technischen Fortschritt läuft Wachstum aus. In alternden Gesellschaften wie Deutschland schrumpft zudem der Faktor Arbeit; Wachstum muss dann fast vollständig aus Produktivität kommen." },
  { id: "vma-012", cat: "vwl", topic: "Wachstum", type: "number", emoji: "⏳", level: 2,
    value: "35 Jahre", label: "bis sich das BIP bei 2 % Wachstum verdoppelt",
    text: "Faustregel (**70er-Regel**): 70 ÷ Wachstumsrate in % = Verdopplungszeit. Bei 1 % dauert es 70 Jahre, bei 7 % nur 10 Jahre.",
    more: "Kleine Unterschiede summieren sich über Jahrzehnte enorm – deshalb streiten Ökonomen um Zehntelprozente. Die Regel funktioniert auch rückwärts für Inflation: Bei 3 % Inflation halbiert sich die Kaufkraft in gut 23 Jahren." },
  { id: "vma-013", cat: "vwl", topic: "Wachstum", type: "flashcard", emoji: "⚙️", level: 1,
    term: "Arbeitsproduktivität",
    def: "Produktion (reales BIP) je Arbeitsstunde oder je Erwerbstätigem. Sie bestimmt langfristig, wie stark die Reallöhne steigen können.",
    example: "Steigt die Produktivität um 2 %, können die Reallöhne um 2 % steigen, ohne dass die Lohnstückkosten zunehmen." },
  { id: "vma-014", cat: "vwl", topic: "Wachstum", type: "truefalse", emoji: "🐢", level: 2,
    q: "Das Produktivitätswachstum in Deutschland hat sich seit den 2000er-Jahren deutlich verlangsamt.",
    answer: true,
    explain: "Wie in fast allen Industrieländern wächst die Stundenproduktivität seit der Finanzkrise nur schwach, oft unter 1 % pro Jahr. Diskutierte Gründe: Rückstand bei Digitalisierung, Bürokratie, schwache Investitionen, Verschiebung zu Dienstleistungen." },
  { id: "vma-015", cat: "vwl", topic: "Wachstum", type: "quiz", emoji: "💻", level: 2,
    q: "Was beschreibt das „Produktivitätsparadox“ von Robert Solow (1987)?",
    options: ["Längere Arbeitszeiten senken die Produktivität", "Hohe Löhne verringern die Produktivität", "Produktivität steigt nur in Rezessionen", "Computer sieht man überall – nur nicht in der Produktivitätsstatistik"],
    answer: 3,
    explain: "Neue Technologien wirken oft erst mit großer Verzögerung, wenn Prozesse und Organisationen umgebaut sind. Dieselbe Debatte läuft heute über Künstliche Intelligenz." },
  { id: "vma-016", cat: "vwl", topic: "Wachstum", type: "whatif", emoji: "📉", level: 3,
    q: "Was passiert, wenn die Erwerbsbevölkerung schrumpft und die Produktivität stagniert?",
    steps: ["Weniger Arbeitsstunden in der Wirtschaft", "Potenzialwachstum sinkt Richtung null", "Steuer- und Beitragsbasis wächst kaum", "Verteilungskonflikte (Rente, Haushalt)"],
    text: "Potenzialwachstum ≈ Wachstum der Arbeitsstunden + Produktivitätswachstum. Für Deutschland schätzen Institute und Bundesregierung es nur noch auf deutlich unter 1 % pro Jahr (Stand 2025). Hebel: Zuwanderung, mehr Erwerbsbeteiligung, Investitionen, Innovation." },

  // ───────── Konjunktur ─────────
  { id: "vma-017", cat: "vwl", topic: "Konjunktur", type: "order", emoji: "🎢", level: 1,
    q: "Bring die Phasen des Konjunkturzyklus in die richtige Reihenfolge (ab dem Tiefpunkt).",
    items: ["Tiefphase (Depression)", "Aufschwung (Expansion)", "Boom (Hochkonjunktur)", "Abschwung (Rezession)"],
    explain: "Im Aufschwung steigen Aufträge und Beschäftigung, im Boom sind Kapazitäten ausgelastet und Preise steigen. Im Abschwung sinken Investitionen und Produktion, bis die Talsohle erreicht ist." },
  { id: "vma-018", cat: "vwl", topic: "Konjunktur", type: "flashcard", emoji: "✌️", level: 1,
    term: "Technische Rezession",
    def: "Zwei Quartale in Folge mit sinkendem realem BIP gegenüber dem Vorquartal (saison- und kalenderbereinigt).",
    example: "Nur eine Faustregel: In den USA stellt ein Komitee des NBER Rezessionen anhand vieler Daten fest (Beschäftigung, Einkommen, Produktion)." },
  { id: "vma-019", cat: "vwl", topic: "Konjunktur", type: "fact", emoji: "🌡️", level: 1,
    title: "ifo-Geschäftsklima: Deutschlands wichtigster Frühindikator",
    text: "Das ifo Institut in München befragt monatlich rund 9.000 Unternehmen nach ihrer aktuellen Lage und ihren Erwartungen für die nächsten sechs Monate. Daraus entsteht der Geschäftsklimaindex.",
    more: "**Frühindikatoren** laufen der Konjunktur voraus (ifo, ZEW, Einkaufsmanagerindex, Auftragseingänge). **Präsenzindikatoren** laufen gleich (Produktion, BIP), **Spätindikatoren** hinterher (Arbeitslosigkeit). Merkhilfe: Der Arbeitsmarkt reagiert zuletzt." },
  { id: "vma-020", cat: "vwl", topic: "Konjunktur", type: "quiz", emoji: "🐌", level: 2,
    q: "Welcher Indikator gilt als Spätindikator der Konjunktur?",
    options: ["ifo-Geschäftserwartungen", "Auftragseingänge der Industrie", "Einkaufsmanagerindex (PMI)", "Arbeitslosenquote"],
    answer: 3,
    explain: "Firmen entlassen erst, wenn der Abschwung sicher ist (vorher: Überstunden abbauen, Kurzarbeit), und stellen erst ein, wenn der Aufschwung trägt. Daher reagiert die Arbeitslosigkeit mit Verzögerung." },
  { id: "vma-021", cat: "vwl", topic: "Konjunktur", type: "truefalse", emoji: "🕳️", level: 1,
    q: "Eine technische Rezession ist dasselbe wie eine Depression.",
    answer: false,
    explain: "Eine technische Rezession kann sehr mild sein (z. B. −0,1 % in zwei Quartalen). Eine **Depression** ist ein tiefer, langer Einbruch mit Massenarbeitslosigkeit – wie die Weltwirtschaftskrise ab 1929." },
  { id: "vma-022", cat: "vwl", topic: "Konjunktur", type: "whatif", emoji: "📦", level: 1,
    q: "Was passiert, wenn die Auftragseingänge der Industrie monatelang fallen?",
    steps: ["Firmen arbeiten Auftragsbestand ab", "Produktion sinkt mit Verzögerung", "Erst Überstunden weg, dann Kurzarbeit", "Investitionen werden verschoben", "BIP-Prognosen werden gesenkt"],
    text: "Aufträge sind die Produktion von morgen. Deshalb beobachten Ökonomen sie als Frühindikator – vor allem in Deutschland mit seinem großen Industrieanteil." },
  { id: "vma-023", cat: "vwl", topic: "Konjunktur", type: "whatif", emoji: "🦁", level: 2,
    q: "Was passiert, wenn Unternehmen pessimistisch werden, obwohl sich objektiv wenig geändert hat?",
    steps: ["Firmen verschieben Investitionen", "Zulieferer erhalten weniger Aufträge", "Neueinstellungen werden gestoppt", "Haushalte sparen vorsichtshalber", "Der Abschwung tritt tatsächlich ein"],
    text: "Erwartungen können sich selbst erfüllen. Keynes sprach von **„Animal Spirits“**: Stimmung treibt Investitionen. Darum werden Stimmungsindikatoren wie ifo und ZEW an den Märkten so genau verfolgt." },
  { id: "vma-024", cat: "vwl", topic: "Konjunktur", type: "quiz", emoji: "🔭", level: 3,
    q: "Wen befragt das ZEW (Mannheim) für seine monatlichen Konjunkturerwartungen?",
    options: ["Verbraucherinnen und Verbraucher", "Einzelhändler", "Finanzmarktexperten wie Analysten und Anleger", "Gewerkschaften"],
    answer: 2,
    explain: "Der ZEW-Index spiegelt die Sicht der Finanzmärkte und reagiert oft schneller als der ifo-Index, der Unternehmen befragt. Er erscheint früh im Monat und bewegt deshalb die Börsen." },
  { id: "vma-025", cat: "vwl", topic: "Konjunktur", type: "flashcard", emoji: "↕️", level: 3,
    term: "Produktionslücke (Output Gap)",
    def: "Tatsächliches BIP minus Produktionspotenzial (BIP bei normaler Auslastung). Negativ: Unterauslastung, Arbeitslosigkeit, wenig Preisdruck. Positiv: Überhitzung, Inflationsdruck.",
    example: "Die Konjunkturkomponente der Schuldenbremse erlaubt bei negativer Lücke mehr Kredite – und verlangt im Boom weniger." },

  // ───────── Inflation ─────────
  { id: "vma-026", cat: "vwl", topic: "Inflation", type: "fact", emoji: "🧺", level: 1,
    title: "Der Verbraucherpreisindex misst einen Warenkorb",
    text: "Das Statistische Bundesamt erfasst monatlich die Preise von rund 650 Güterarten – von Brot über Miete bis Pauschalreise. Gewichtet wird nach Ausgabenanteilen der Haushalte (Wägungsschema), das regelmäßig aktualisiert wird.",
    more: "Für den Euroraum nutzt die EZB den **HVPI** (Harmonisierter VPI) mit EU-weit einheitlicher Methode. Weil Gewichte und Abgrenzungen leicht abweichen, unterscheiden sich VPI und HVPI für Deutschland oft um einige Zehntelpunkte." },
  { id: "vma-027", cat: "vwl", topic: "Inflation", type: "flashcard", emoji: "🎯", level: 1,
    term: "Kerninflation",
    def: "Inflationsrate ohne die besonders schwankungsanfälligen Komponenten Energie und Nahrungsmittel (im Euroraum meist auch ohne Alkohol und Tabak).",
    example: "Sie zeigt den zugrunde liegenden Preistrend. Für die EZB wichtig: Auf kurzfristige Ölpreissprünge hat sie kaum Einfluss, auf hartnäckige Kerninflation schon." },
  { id: "vma-028", cat: "vwl", topic: "Inflation", type: "number", emoji: "🔥", level: 1,
    value: "6,9 %", label: "Inflationsrate in Deutschland 2022 (VPI)",
    text: "Treiber waren Energie und Lebensmittel nach dem russischen Angriff auf die Ukraine. Die Monatsrate erreichte im Herbst 2022 fast 9 %. 2023 lag die Jahresrate bei 5,9 %, 2024 bei 2,2 %.",
    more: "Im Euroraum gipfelte die Inflation im Oktober 2022 bei 10,6 %. Mischung aus Angebotsschock (Energie, Lieferketten) und Nachfrageschub nach Corona. Reallöhne sanken 2022 deutlich – erst 2024 holten sie wieder auf." },
  { id: "vma-029", cat: "vwl", topic: "Inflation", type: "quiz", emoji: "🛢️", level: 1,
    q: "Welches Ereignis ist ein klassischer Angebotsschock?",
    options: ["Der Staat senkt die Einkommensteuer", "Ein Ölembargo verteuert Energie massiv", "Die Zentralbank senkt die Zinsen", "Der Staat erhöht die Rüstungsausgaben"],
    answer: 1,
    explain: "Ein Angebotsschock verteuert die Produktion: Preise steigen, während Produktion und Beschäftigung sinken. Die anderen drei Optionen erhöhen die Nachfrage." },
  { id: "vma-030", cat: "vwl", topic: "Inflation", type: "flashcard", emoji: "⚖️", level: 2,
    term: "Nachfrage- vs. Kosteninflation",
    def: "**Nachfragesog (demand-pull):** Die Nachfrage übersteigt die Kapazitäten – Preise und Produktion steigen. **Kostendruck (cost-push):** Energie, Rohstoffe oder Löhne verteuern sich – Preise steigen, Produktion sinkt.",
    example: "2021/22 kam beides zusammen: Nachholkonsum nach Corona plus Energie- und Lieferkettenschock." },
  { id: "vma-031", cat: "vwl", topic: "Inflation", type: "whatif", emoji: "🌀", level: 2,
    q: "Was passiert, wenn Gewerkschaften die Inflation voll und dauerhaft über Löhne ausgleichen?",
    steps: ["Löhne steigen stärker als Produktivität", "Lohnstückkosten steigen", "Firmen erhöhen ihre Preise", "Inflation bleibt hoch", "Nächste Lohnrunde fordert noch mehr"],
    text: "Die **Lohn-Preis-Spirale** – Zentralbanken fürchten solche **Zweitrundeneffekte**, weil sie Inflation verfestigen. 2022/23 setzte Deutschland auch auf steuerfreie Inflationsausgleichsprämien bis 3.000 €, die nicht dauerhaft in die Tariflöhne eingingen." },
  { id: "vma-032", cat: "vwl", topic: "Inflation", type: "truefalse", emoji: "🏷️", level: 2,
    q: "Allgemein fallende Preise (Deflation) sind gut für die Wirtschaft, weil alles billiger wird.",
    answer: false,
    explain: "Breite Deflation lädt zum Abwarten ein: Käufe werden verschoben, Umsätze und Löhne sinken, die reale Schuldenlast steigt. Japan kämpfte ab den 1990ern jahrzehntelang damit. Deshalb zielen Zentralbanken auf 2 % statt 0 %." },
  { id: "vma-033", cat: "vwl", topic: "Inflation", type: "whatif", emoji: "🧊", level: 2,
    q: "Was passiert, wenn alle erwarten, dass die Preise nächstes Jahr fallen?",
    steps: ["Haushalte verschieben Anschaffungen", "Firmen verkaufen weniger, senken Preise", "Löhne und Investitionen sinken", "Reale Schuldenlast steigt", "Nachfrage sinkt weiter"],
    text: "Eine **Deflationsspirale**. Besonders gefährlich, weil die Zentralbank die Zinsen kaum unter null senken kann (Zinsuntergrenze) – genau dann, wenn die Realzinsen durch fallende Preise steigen." },
  { id: "vma-034", cat: "vwl", topic: "Inflation", type: "fact", emoji: "🥶", level: 2,
    title: "Stagflation: das Schlimmste aus zwei Welten",
    text: "Stagnation + Inflation gleichzeitig: hohe Preissteigerung, schwaches Wachstum, steigende Arbeitslosigkeit. Typischer Auslöser sind Angebotsschocks wie die Ölkrisen der 1970er.",
    more: "Das Dilemma der Zentralbank: Zinserhöhungen gegen Inflation verschärfen die Rezession, Zinssenkungen heizen die Inflation an. Fed-Chef Paul Volcker wählte ab 1979 extreme Zinserhöhungen (Leitzins zeitweise bei rund 20 %) – mit schwerer Rezession, aber dauerhaftem Erfolg." },
  { id: "vma-035", cat: "vwl", topic: "Inflation", type: "quiz", emoji: "💸", level: 2,
    q: "Wer verliert typischerweise bei unerwartet hoher Inflation?",
    options: ["Schuldner mit Festzinskredit", "Der Staat als großer Schuldner", "Besitzer von vermieteten Immobilien", "Sparer mit Festgeld, dessen Zins unter der Inflation liegt"],
    answer: 3,
    explain: "Inflation entwertet Geldforderungen und Geldschulden gleichermaßen. Gläubiger (Sparer) verlieren real, Schuldner (inkl. Staat) gewinnen – sie zahlen mit „weniger wertvollem“ Geld zurück." },
  { id: "vma-036", cat: "vwl", topic: "Inflation", type: "quiz", emoji: "➗", level: 3,
    q: "Ein Festgeld bringt 3 % Zinsen, die Inflation liegt bei 5 %. Wie hoch ist der Realzins ungefähr?",
    options: ["+8 %", "+2 %", "−2 %", "0 %"],
    answer: 2,
    explain: "**Fisher-Gleichung:** Realzins ≈ Nominalzins − Inflationsrate = 3 % − 5 % = −2 %. Die Kaufkraft des Ersparten schrumpft also, obwohl der Kontostand wächst." },
  { id: "vma-037", cat: "vwl", topic: "Inflation", type: "whatif", emoji: "🖨️", level: 1,
    q: "Was passiert, wenn die Zentralbank Geld druckt, ohne dass die Wirtschaft wächst?",
    steps: ["Geldmenge steigt, Gütermenge nicht", "Mehr Geld jagt gleich viele Güter", "Preise steigen", "Geld verliert Kaufkraft", "Vertrauen in die Währung kann kippen"],
    text: "**Quantitätsgleichung** M · V = P · Y: Bleiben Umlaufgeschwindigkeit V und reale Produktion Y gleich, steigen die Preise P mit der Geldmenge M. Extremfälle: Deutschland 1923, Simbabwe 2008. In der Praxis ist V aber nicht stabil – darum wirkt mehr Geld nicht immer sofort." },
  { id: "vma-038", cat: "vwl", topic: "Inflation", type: "truefalse", emoji: "🏦", level: 3,
    q: "Die massiven Anleihekäufe der EZB ab 2015 lösten sofort hohe Inflation aus.",
    answer: false,
    explain: "Bis 2021 lag die Inflation im Euroraum meist unter 2 %. Das neue Zentralbankgeld blieb großteils als Reserven der Banken bei der EZB liegen; Kredite und Nachfrage wuchsen nur langsam. Hohe Inflation kam erst 2021/22 mit Energieschock, Lieferengpässen und Nachholnachfrage." },
  { id: "vma-039", cat: "vwl", topic: "Inflation", type: "truefalse", emoji: "🧠", level: 1,
    q: "Die „gefühlte“ Inflation liegt oft höher als die gemessene.",
    answer: true,
    explain: "Häufig gekaufte Güter (Lebensmittel, Sprit) prägen die Wahrnehmung, seltene Käufe wie Elektronik – die oft billiger wird – kaum. Preiserhöhungen merkt man sich stärker als Senkungen. Und jeder Haushalt hat seinen eigenen Warenkorb." },
  { id: "vma-040", cat: "vwl", topic: "Inflation", type: "whatif", emoji: "⚓", level: 3,
    q: "Was passiert, wenn sich die Inflationserwartungen vom 2-%-Ziel lösen?",
    steps: ["Firmen kalkulieren höhere Preise ein", "Beschäftigte fordern höhere Löhne", "Inflation verfestigt sich", "Zentralbank muss Zinsen stärker erhöhen", "Rezession wird wahrscheinlicher"],
    text: "**Verankerte Erwartungen** sind das wichtigste Kapital einer Zentralbank: Solange alle an 2 % glauben, verpuffen Schocks schneller. Deshalb kommuniziert die EZB so intensiv und reagiert eher zu hart als zu weich, wenn Erwartungen wackeln." },

  // ───────── Arbeitsmarkt ─────────
  { id: "vma-041", cat: "vwl", topic: "Arbeitsmarkt", type: "flashcard", emoji: "🧩", level: 1,
    term: "Arten der Arbeitslosigkeit",
    def: "**Friktionell:** Suchzeit beim Jobwechsel · **Saisonal:** z. B. Bau im Winter · **Konjunkturell:** zu wenig Nachfrage · **Strukturell:** Qualifikation oder Region passen nicht zu den offenen Stellen.",
    example: "Gibt es gleichzeitig viele Arbeitslose und viele offene Stellen, spricht das für strukturelle Arbeitslosigkeit (Mismatch)." },
  { id: "vma-042", cat: "vwl", topic: "Arbeitsmarkt", type: "quiz", emoji: "⛏️", level: 1,
    q: "Ein Bergmann verliert nach der Zechenschließung seinen Job, während IT-Firmen händeringend suchen. Welche Arbeitslosigkeit ist das?",
    options: ["Friktionelle", "Saisonale", "Konjunkturelle", "Strukturelle"],
    answer: 3,
    explain: "Die Stellen gibt es, aber Qualifikation (und oft Region) passen nicht. Gegenmittel sind Umschulung und Weiterbildung – Konjunkturprogramme helfen hier kaum." },
  { id: "vma-043", cat: "vwl", topic: "Arbeitsmarkt", type: "fact", emoji: "📈", level: 2,
    title: "Phillips-Kurve: weniger Arbeitslose, mehr Inflation?",
    text: "A. W. Phillips fand 1958 für Großbritannien: Bei niedriger Arbeitslosigkeit steigen die Löhne schneller. Später wurde daraus ein Zielkonflikt: etwas mehr Inflation gegen weniger Arbeitslosigkeit.",
    more: "Die 1970er widerlegten die dauerhafte Version: Erwartungen passen sich an, man bekommt beides (Friedman/Phelps). Helmut Schmidt wird der Satz „Lieber 5 % Inflation als 5 % Arbeitslosigkeit“ zugeschrieben – am Ende hatte Deutschland zeitweise beides." },
  { id: "vma-044", cat: "vwl", topic: "Arbeitsmarkt", type: "number", emoji: "👥", level: 1,
    value: "≈ 3 Mio.", label: "registrierte Arbeitslose in Deutschland (Stand 2025)",
    text: "Erstmals seit rund zehn Jahren wieder um die 3-Millionen-Marke (Quote gut 6 %) – Folge der langen Industrieschwäche. Zum Vergleich: 2005 waren es im Jahresschnitt fast 4,9 Mio.",
    more: "Gleichzeitig arbeiten so viele Menschen wie nie und viele Branchen klagen über Fachkräftemangel – der Arbeitsmarkt ist gespalten. Die international vergleichbare ILO-Erwerbslosenquote liegt mit unter 4 % deutlich niedriger, weil sie anders zählt." },
  { id: "vma-045", cat: "vwl", topic: "Arbeitsmarkt", type: "truefalse", emoji: "🤒", level: 2,
    q: "Deutschland galt um die Jahrtausendwende als „kranker Mann Europas“.",
    answer: true,
    explain: "Schwaches Wachstum, bis zu knapp 5 Mio. Arbeitslose (2005). Es folgten Agenda 2010/Hartz-Reformen, Lohnzurückhaltung und ein Exportboom. Seit 2023 taucht das Etikett wegen der Stagnation wieder auf." },
  { id: "vma-046", cat: "vwl", topic: "Arbeitsmarkt", type: "number", emoji: "⏸️", level: 2,
    value: "≈ 6 Mio.", label: "Menschen in Kurzarbeit im April 2020 (Corona)",
    text: "Rekord: In der Finanzkrise 2009 waren es in der Spitze rund 1,4 Mio. Kurzarbeit hält Beschäftigte im Betrieb, statt sie zu entlassen – die Bundesagentur ersetzt einen Teil des Lohnausfalls.",
    more: "Vorteil: Firmen behalten eingearbeitete Fachkräfte und können im Aufschwung sofort hochfahren. Risiko: Bei echtem Strukturwandel konserviert Kurzarbeit Jobs, die nicht zurückkommen. International wurde das Modell nach 2009 vielfach kopiert." },
  { id: "vma-047", cat: "vwl", topic: "Arbeitsmarkt", type: "whatif", emoji: "💶", level: 2,
    q: "Was passiert, wenn der Mindestlohn deutlich steigt?",
    steps: ["Geringverdiener erhalten mehr Lohn", "Kosten in Niedriglohnbranchen steigen", "Teils höhere Preise (Friseur, Gastro)", "Schwache Firmen bauen evtl. Jobs ab", "Kaufkraft unten steigt"],
    text: "Bei der Einführung 2015 (8,50 €) wurden Hunderttausende Jobverluste befürchtet; Studien fanden kaum Beschäftigungsverluste, aber weniger Minijobs. Entscheidend ist die Höhe relativ zum Medianlohn. Stand: 12,82 € (2025), 13,90 € ab 2026." },
  { id: "vma-048", cat: "vwl", topic: "Arbeitsmarkt", type: "whatif", emoji: "🔧", level: 3,
    q: "Was passiert, wenn Fachkräfte dauerhaft knapp sind?",
    steps: ["Offene Stellen bleiben unbesetzt", "Löhne in Engpassberufen steigen", "Aufträge werden abgelehnt", "Firmen automatisieren oder verlagern", "Zuwanderung wird zum Wachstumsfaktor"],
    text: "Fachkräftemangel bremst das Produktionspotenzial – Nachfrageprogramme helfen dann wenig, weil die Arbeitskräfte fehlen. Hebel sind Ausbildung, Zuwanderung, mehr Vollzeit für Teilzeitkräfte und längeres Arbeiten." },
  { id: "vma-049", cat: "vwl", topic: "Arbeitsmarkt", type: "quiz", emoji: "🔗", level: 2,
    q: "Was beschreibt das Okunsche Gesetz?",
    options: ["Den Zusammenhang von Geldmenge und Preisen", "Den Zusammenhang von Zinsen und Wechselkurs", "Den Zusammenhang von Wirtschaftswachstum und Arbeitslosigkeit", "Den Zusammenhang von Steuersätzen und Steuereinnahmen"],
    answer: 2,
    explain: "Faustregel: Wächst das BIP deutlich unter seinem Potenzial, steigt die Arbeitslosigkeit. In Deutschland ist der Zusammenhang schwächer als in den USA, weil Kurzarbeit und Kündigungsschutz Entlassungen dämpfen." },

  // ───────── Geldschöpfung ─────────
  { id: "vma-050", cat: "vwl", topic: "Geldschöpfung", type: "fact", emoji: "⌨️", level: 1,
    title: "Banken schaffen Geld per Kredit",
    text: "Der Großteil unseres Geldes ist **Giralgeld** (Buchgeld auf Konten). Es entsteht, wenn eine Geschäftsbank einen Kredit vergibt: Sie schreibt dem Kunden den Betrag gut – neues Geld per Buchung. Wird der Kredit getilgt, verschwindet es wieder.",
    more: "Bargeld macht nur rund ein Zehntel der breiten Geldmenge M3 im Euroraum aus. Grenzen der Geldschöpfung: Kreditnachfrage, Zinsniveau, Eigenkapitalvorschriften und der Bedarf an Zentralbankgeld (Mindestreserve, Bargeld, Zahlungen zwischen Banken)." },
  { id: "vma-051", cat: "vwl", topic: "Geldschöpfung", type: "flashcard", emoji: "🏛️", level: 2,
    term: "Zentralbankgeld",
    def: "Bargeld plus Guthaben der Geschäftsbanken bei der Zentralbank (Reserven). Nur die Zentralbank kann es erzeugen – etwa durch Kredite an Banken oder Wertpapierkäufe.",
    example: "Banken brauchen es für Bargeldauszahlungen, die Mindestreserve und Überweisungen an andere Banken." },
  { id: "vma-052", cat: "vwl", topic: "Geldschöpfung", type: "truefalse", emoji: "🐷", level: 2,
    q: "Banken können nur das Geld verleihen, das Sparer vorher eingezahlt haben.",
    answer: false,
    explain: "Umgekehrt: Der Kredit schafft die Einlage. Die Bank of England hat das 2014 ausführlich erklärt. Banken brauchen danach Zentralbankgeld und Eigenkapital, aber nicht vorher Spareinlagen in gleicher Höhe." },
  { id: "vma-053", cat: "vwl", topic: "Geldschöpfung", type: "quiz", emoji: "🪙", level: 2,
    q: "Was umfasst die Geldmenge M1?",
    options: ["Nur das Bargeld", "Bargeld und täglich fällige Einlagen (Girokonten)", "Bargeld, Sicht- und Termineinlagen bis 2 Jahre", "Alle Wertpapiere im Euroraum"],
    answer: 1,
    explain: "M1 ist das „Zahlungsmittel“-Geld. M2 nimmt kurzfristige Termin- und Spareinlagen hinzu, M3 zusätzlich Geldmarktfondsanteile, Repos und kurzlaufende Schuldverschreibungen. Die EZB beobachtet vor allem M3." },
  { id: "vma-054", cat: "vwl", topic: "Geldschöpfung", type: "whatif", emoji: "🏃", level: 1,
    q: "Was passiert, wenn alle Kunden einer Bank gleichzeitig ihr Geld abheben wollen?",
    steps: ["Bank hat nur einen Bruchteil als Reserve", "Sie muss Vermögen hastig verkaufen", "Verluste fressen das Eigenkapital", "Ohne Hilfe droht die Pleite (Bank Run)", "Panik springt auf andere Banken über"],
    text: "Dagegen helfen **Einlagensicherung** (in der EU 100.000 € je Kunde und Bank) und die Zentralbank als „Lender of Last Resort“. Beispiel: der Run auf die Silicon Valley Bank 2023 – diesmal per Smartphone in Stunden." },
  { id: "vma-055", cat: "vwl", topic: "Geldschöpfung", type: "number", emoji: "🧷", level: 3,
    value: "1 %", label: "Mindestreservesatz im Euroraum (seit 2012)",
    text: "Banken müssen 1 % bestimmter Kundeneinlagen als Guthaben bei der Zentralbank halten. Bis 2012 waren es 2 %. Seit September 2023 wird die Mindestreserve nicht mehr verzinst.",
    more: "Der Lehrbuch-Geldschöpfungsmultiplikator (1 ÷ Reservesatz) suggeriert eine feste Kette. In der Praxis steuert die EZB nicht die Geldmenge, sondern den Zins – und stellt Zentralbankgeld bereit, wenn Banken es brauchen." },
  { id: "vma-056", cat: "vwl", topic: "Geldschöpfung", type: "whatif", emoji: "🗜️", level: 3,
    q: "Was passiert, wenn Banken nach hohen Verlusten kaum noch Kredite vergeben?",
    steps: ["Firmen bekommen keine Finanzierung", "Investitionen werden gestrichen", "Geldmenge wächst kaum oder schrumpft", "Nachfrage und Preisdruck sinken", "Die Rezession vertieft sich"],
    text: "Eine **Kreditklemme** (Credit Crunch) wie 2008/09. Darum stützen Staaten in Krisen das Eigenkapital der Banken und Zentralbanken fluten den Geldmarkt mit Liquidität." },
  { id: "vma-057", cat: "vwl", topic: "Geldschöpfung", type: "quiz", emoji: "📜", level: 1,
    q: "Was „deckt“ den Euro heute?",
    options: ["Die Goldreserven der EZB", "Dollar-Reserven in fester Quote", "Staatsanleihen in fester Quote", "Vertrauen in die Zentralbank und die Wirtschaftskraft (Fiatgeld)"],
    answer: 3,
    explain: "Seit dem Ende von Bretton Woods (1971/73) sind die großen Währungen **Fiatgeld**: Sie gelten, weil sie gesetzliches Zahlungsmittel sind und Menschen ihnen vertrauen. Dieses Vertrauen hängt an stabiler Kaufkraft." },

  // ───────── EZB ─────────
  { id: "vma-058", cat: "vwl", topic: "EZB", type: "number", emoji: "🎯", level: 1,
    value: "2 %", label: "Inflationsziel der EZB (mittelfristig, symmetrisch)",
    text: "Seit der Strategieüberprüfung 2021 gilt: Abweichungen nach oben und unten sind gleich unerwünscht. Vorher lautete das Ziel „unter, aber nahe 2 %“.",
    more: "Warum nicht 0 %? Ein Puffer gegen Deflation, Messfehler (Qualitätsverbesserungen werden unterschätzt) und Spielraum für Zinssenkungen in Krisen. Auch Fed und Bank of England zielen auf 2 %." },
  { id: "vma-059", cat: "vwl", topic: "EZB", type: "fact", emoji: "📘", level: 1,
    title: "Vorrangiges Ziel der EZB: Preisstabilität",
    text: "So steht es im EU-Vertrag (Art. 127 AEUV). Nur soweit dies die Preisstabilität nicht gefährdet, unterstützt die EZB die allgemeine Wirtschaftspolitik der EU. Sitz ist Frankfurt am Main, Gründung 1998.",
    more: "Vorbild war die Deutsche Bundesbank – geprägt von der Erfahrung der Hyperinflation 1923. Die US-Notenbank Fed hat dagegen ein **duales Mandat**: Preisstabilität und maximale Beschäftigung gleichrangig." },
  { id: "vma-060", cat: "vwl", topic: "EZB", type: "flashcard", emoji: "🎚️", level: 2,
    term: "Die drei Leitzinsen der EZB",
    def: "**Einlagesatz:** Zins für Bankguthaben über Nacht · **Hauptrefinanzierungssatz:** Zins für einwöchige Kredite an Banken · **Spitzenrefinanzierungssatz:** teurer Übernachtkredit im Notfall.",
    example: "Weil Banken heute reichlich Reserven haben, steuert faktisch der Einlagesatz die Geldmarktzinsen – Medien meinen meist ihn, wenn vom „Leitzins“ die Rede ist." },
  { id: "vma-061", cat: "vwl", topic: "EZB", type: "event", emoji: "🔄", level: 2,
    year: "2022", title: "Zinswende: EZB beendet die Negativzinsen",
    text: "Im Juli 2022 erhöhte die EZB erstmals seit elf Jahren die Zinsen – gleich um 0,5 Prozentpunkte. Bis September 2023 stieg der Einlagesatz in zehn Schritten von −0,5 % auf 4,0 %.",
    more: "Die schnellste Straffung in der Geschichte der EZB. Kritik: Sie kam spät, die Inflation lag da schon bei über 8 %. Ab Juni 2024 senkte die EZB wieder; Mitte 2025 lag der Einlagesatz bei 2,0 %." },
  { id: "vma-062", cat: "vwl", topic: "EZB", type: "whatif", emoji: "⬆️", level: 1,
    q: "Was passiert, wenn die EZB die Zinsen erhöht?",
    steps: ["Kredite teurer, Sparen attraktiver", "Weniger Investitionen und Baukredite", "Konsum und Nachfrage schwächen sich ab", "Euro wertet tendenziell auf", "Inflation sinkt nach 1–2 Jahren"],
    text: "Das ist der **Transmissionsmechanismus**. Die Wirkung kommt mit langen, schwankenden Verzögerungen (Milton Friedman: „long and variable lags“). Nebenwirkung 2023: Der Wohnungsbau brach ein, weil Baufinanzierungen sich mehr als verdoppelten." },
  { id: "vma-063", cat: "vwl", topic: "EZB", type: "whatif", emoji: "🛍️", level: 2,
    q: "Was passiert, wenn die EZB massenhaft Staatsanleihen kauft (Quantitative Easing)?",
    steps: ["Nachfrage nach Anleihen steigt", "Kurse steigen, Renditen fallen", "Langfristige Zinsen sinken", "Anleger weichen in Aktien und Immobilien aus", "Kredite und Vermögenspreise steigen"],
    text: "Die EZB nutzte QE ab 2015, als der Leitzins schon bei null lag. Nebenwirkungen: steigende Vermögenspreise (wer Vermögen hat, profitiert) und der Vorwurf verdeckter Staatsfinanzierung – das Bundesverfassungsgericht rügte 2020 die Verhältnismäßigkeitsprüfung." },
  { id: "vma-064", cat: "vwl", topic: "EZB", type: "quiz", emoji: "🛡️", level: 2,
    q: "Warum ist die EZB politisch unabhängig?",
    options: ["Damit Regierungen nicht vor Wahlen die Geldpresse anwerfen", "Damit sie Staaten billiger finanzieren kann", "Weil die EU sie nicht finanzieren kann", "Damit Geschäftsbanken sie kontrollieren"],
    answer: 0,
    explain: "Politiker haben einen Anreiz, kurzfristig Wachstum zu kaufen und die Inflationsrechnung später zu zahlen. Studien zeigen: Unabhängige Zentralbanken gehen mit niedrigerer Inflation einher. Glaubwürdigkeit ist ihr Kapital." },
  { id: "vma-065", cat: "vwl", topic: "EZB", type: "truefalse", emoji: "🚫", level: 2,
    q: "Die EZB darf neu ausgegebene Staatsanleihen direkt von Euro-Staaten kaufen.",
    answer: false,
    explain: "Art. 123 AEUV verbietet die monetäre Staatsfinanzierung, also den Direktkauf bei Emission. Erlaubt sind Käufe am Sekundärmarkt von anderen Anlegern – unter Auflagen. Darauf beruhen QE und die Krisenprogramme." },
  { id: "vma-066", cat: "vwl", topic: "EZB", type: "quiz", emoji: "🗳️", level: 2,
    q: "Wer entscheidet über die Leitzinsen im Euroraum?",
    options: ["Die Eurogruppe der Finanzminister", "Die EU-Kommission", "Der EZB-Rat: Direktorium plus Präsidenten der nationalen Zentralbanken", "Das Europäische Parlament"],
    answer: 2,
    explain: "Der EZB-Rat besteht aus den sechs Direktoriumsmitgliedern und den Chefs der nationalen Zentralbanken des Euroraums (Stimmrechte rotieren). Präsidentin ist seit 2019 Christine Lagarde; Deutschland vertritt der Bundesbank-Präsident." },
  { id: "vma-067", cat: "vwl", topic: "EZB", type: "number", emoji: "🥶", level: 2,
    value: "−0,5 %", label: "tiefster Einlagesatz der EZB (2019–2022)",
    text: "Banken mussten für Guthaben bei der EZB Strafzinsen zahlen – viele gaben das als „Verwahrentgelt“ an Kunden mit großen Guthaben weiter. Negative Zinsen galten von 2014 bis Juli 2022.",
    more: "Ziel: Banken sollten Geld verleihen statt parken. Nebenwirkungen: belastete Bankmargen, Druck auf Lebensversicherer und Sparer, steigende Immobilienpreise. Die Schweiz ging bis −0,75 %." },
  { id: "vma-068", cat: "vwl", topic: "EZB", type: "whatif", emoji: "🇮🇹", level: 3,
    q: "Was passiert, wenn die Zinsen steigen und Anleger an Italiens Finanzen zweifeln?",
    steps: ["Renditeabstand (Spread) zu Bunds wächst", "Italiens Zinslast steigt", "Schuldentragfähigkeit wird bezweifelt", "Leitzinsen wirken ungleich (Fragmentierung)", "EZB kann mit dem TPI eingreifen"],
    text: "Die EZB schuf 2022 das **Transmission Protection Instrument**: gezielte Anleihekäufe, wenn Spreads ohne fundamentalen Grund ausufern. Ziel ist, dass ein Leitzins für den ganzen Euroraum ähnlich wirkt." },
  { id: "vma-069", cat: "vwl", topic: "EZB", type: "flashcard", emoji: "🔁", level: 3,
    term: "TARGET2-Salden",
    def: "Forderungen und Verbindlichkeiten der nationalen Zentralbanken im Eurosystem, die aus grenzüberschreitenden Zahlungen entstehen. Die Bundesbank hat hohe Forderungen – zeitweise über 1 Bio. €.",
    example: "Überweist ein Italiener Geld auf ein deutsches Konto, entsteht eine Forderung der Bundesbank gegenüber dem Eurosystem. Kritiker wie Hans-Werner Sinn sehen darin ein Risiko bei einem Euro-Austritt." },

  // ───────── Fed vs. EZB ─────────
  { id: "vma-070", cat: "vwl", topic: "Fed vs. EZB", type: "quiz", emoji: "🇺🇸", level: 1,
    q: "Welches Mandat hat die US-Notenbank Federal Reserve (Fed)?",
    options: ["Nur Preisstabilität", "Einen festen Wechselkurs zum Euro", "Preisstabilität und maximale Beschäftigung", "Die Finanzierung des US-Haushalts"],
    answer: 2,
    explain: "Das **duale Mandat** der Fed stellt Beschäftigung gleichrangig neben Preisstabilität. Die EZB hat ein hierarchisches Mandat: zuerst Preisstabilität. In der Praxis zielen beide auf 2 % Inflation." },
  { id: "vma-071", cat: "vwl", topic: "Fed vs. EZB", type: "truefalse", emoji: "⏱️", level: 2,
    q: "Die Fed begann 2022 früher mit Zinserhöhungen als die EZB.",
    answer: true,
    explain: "Die Fed erhöhte ab März 2022, die EZB erst ab Juli 2022. Die Fed ging bis auf 5,25–5,50 % (2023), die EZB bis 4,0 %. Der Zinsvorsprung der USA trug dazu bei, dass der Euro 2022 zeitweise unter 1 Dollar fiel." },
  { id: "vma-072", cat: "vwl", topic: "Fed vs. EZB", type: "whatif", emoji: "💵", level: 2,
    q: "Was passiert, wenn die Fed die Zinsen deutlich stärker erhöht als die EZB?",
    steps: ["Dollar-Anlagen werden attraktiver", "Kapital fließt in die USA", "Dollar wertet auf, Euro ab", "In Dollar bezahltes Öl wird teurer", "Inflationsdruck im Euroraum steigt"],
    text: "Zinsdifferenzen bewegen Wechselkurse. 2022 fiel der Euro erstmals seit 2002 unter die Parität zum Dollar – das verstärkte die importierte Inflation in Europa zusätzlich zum Energieschock." },

  // ───────── Fiskalpolitik ─────────
  { id: "vma-073", cat: "vwl", topic: "Fiskalpolitik", type: "flashcard", emoji: "🏗️", level: 1,
    term: "Fiskalpolitik",
    def: "Steuerung der Wirtschaft über Staatseinnahmen und -ausgaben: Steuern, Investitionen, Transfers. Abzugrenzen von der Geldpolitik der Zentralbank (Zinsen, Liquidität).",
    example: "Die Abwrackprämie 2009 war Fiskalpolitik; eine Leitzinssenkung ist Geldpolitik." },
  { id: "vma-074", cat: "vwl", topic: "Fiskalpolitik", type: "fact", emoji: "✖️", level: 2,
    title: "Der Multiplikator: 1 € Staatsausgabe – mehr als 1 € BIP?",
    text: "Baut der Staat eine Brücke, verdienen Baufirma und Beschäftigte daran und geben einen Teil wieder aus – usw. Einfacher Multiplikator = 1 ÷ (1 − Konsumquote).",
    more: "Bei einer Konsumquote von 0,8 wäre er theoretisch 5. Real ist er viel kleiner (Schätzungen meist um 0,5 bis 1,5), weil Steuern, Sparen und Importe „versickern“. In tiefen Rezessionen und bei Nullzinsen ist er größer als im Boom." },
  { id: "vma-075", cat: "vwl", topic: "Fiskalpolitik", type: "whatif", emoji: "✂️", level: 1,
    q: "Was passiert, wenn der Staat in der Rezession spart?",
    steps: ["Ausgaben sinken, Steuern steigen", "Nachfrage bricht weiter ein", "Firmen entlassen, Steuereinnahmen sinken", "Das Defizit verbessert sich kaum", "Die Rezession vertieft sich"],
    text: "**Prozyklische** Politik verstärkt den Abschwung. Historische Beispiele: Brünings Sparkurs 1930–32 oder die harten Auflagen für Griechenland nach 2010 – das griechische BIP schrumpfte um rund ein Viertel. Keynes empfahl das Gegenteil: antizyklisch handeln." },
  { id: "vma-076", cat: "vwl", topic: "Fiskalpolitik", type: "flashcard", emoji: "🪂", level: 2,
    term: "Automatische Stabilisatoren",
    def: "Teile des Steuer- und Sozialsystems, die ohne neuen Beschluss gegen die Konjunktur wirken: progressive Einkommensteuer, Arbeitslosengeld, Kurzarbeitergeld.",
    example: "Im Abschwung sinken Steuereinnahmen und steigen Sozialausgaben automatisch – das Defizit wächst und stützt die Nachfrage, ganz ohne Konjunkturpaket." },
  { id: "vma-077", cat: "vwl", topic: "Fiskalpolitik", type: "quiz", emoji: "📐", level: 2,
    q: "Welche Maßnahme ist typisch für angebotsorientierte Wirtschaftspolitik?",
    options: ["Ein Konjunkturprogramm für Straßenbau", "Schecks an alle Haushalte", "Höheres Arbeitslosengeld in der Krise", "Bürokratieabbau und niedrigere Unternehmenssteuern"],
    answer: 3,
    explain: "Angebotspolitik will die Produktionsbedingungen verbessern (Kosten, Anreize, Regulierung), Keynesianismus die Nachfrage stützen. Beispiele: Reagan und Thatcher in den 1980ern bzw. die Agenda 2010 in Deutschland." },
  { id: "vma-078", cat: "vwl", topic: "Fiskalpolitik", type: "truefalse", emoji: "🎩", level: 1,
    q: "John Maynard Keynes forderte, dass der Staat immer Schulden machen soll.",
    answer: false,
    explain: "Keynes empfahl **antizyklische** Politik: Defizite im Abschwung, Überschüsse im Aufschwung, um die Schulden wieder abzubauen. In der Praxis wurde der zweite Teil oft vergessen – ein Hauptkritikpunkt am angewandten Keynesianismus." },
  { id: "vma-079", cat: "vwl", topic: "Fiskalpolitik", type: "whatif", emoji: "🧲", level: 3,
    q: "Was passiert, wenn der Staat in der Hochkonjunktur massiv Kredite aufnimmt?",
    steps: ["Staat fragt viel Kapital nach", "Zinsen steigen", "Private Investitionen werden verdrängt", "Kapazitäten sind ohnehin ausgelastet", "Eher mehr Inflation als mehr Wachstum"],
    text: "**Crowding-out:** Staatliche Nachfrage verdrängt private. Stark bei Vollbeschäftigung, schwach in einer Rezession mit brachliegenden Kapazitäten und niedrigen Zinsen. Deshalb ist der Zeitpunkt von Konjunkturpolitik so wichtig." },
  { id: "vma-080", cat: "vwl", topic: "Fiskalpolitik", type: "fact", emoji: "🛑", level: 2,
    title: "Die Schuldenbremse im Grundgesetz",
    text: "Seit 2009 in der Verfassung: Der Bund darf strukturell höchstens 0,35 % des BIP an neuen Krediten aufnehmen. Ausnahmen gibt es für Notlagen; eine Konjunkturkomponente erlaubt im Abschwung mehr Defizit.",
    more: "2025 wurde das Grundgesetz geändert: Verteidigungsausgaben über 1 % des BIP sind ausgenommen, dazu kommt ein Sondervermögen von 500 Mrd. € für Infrastruktur und Klimaneutralität. Die Länder dürfen nun ebenfalls 0,35 % des BIP aufnehmen." },
  { id: "vma-081", cat: "vwl", topic: "Fiskalpolitik", type: "whatif", emoji: "🚧", level: 2,
    q: "Was passiert, wenn der Staat Hunderte Milliarden zusätzlich in Infrastruktur steckt?",
    steps: ["Bauaufträge und Nachfrage steigen", "Kurzfristig mehr BIP und Beschäftigung", "Engpässe: Personal, Planung, Baupreise", "Langfristig höheres Produktionspotenzial", "Zinslast und Schuldenquote steigen"],
    text: "Ob es wirkt, hängt daran, ob das Geld schnell und sinnvoll verbaut wird und ob es echte Zusatzinvestitionen sind – statt nur umgebuchter Ausgaben. Ausgelastete Baubranchen lassen sonst vor allem die Preise steigen." },
  { id: "vma-082", cat: "vwl", topic: "Fiskalpolitik", type: "order", emoji: "🔁", level: 2,
    q: "Sortiere die Multiplikator-Kette nach einer staatlichen Brückenbestellung.",
    items: ["Staat bestellt Brücke für 1 Mrd. €", "Baufirma zahlt Löhne und Material", "Beschäftigte konsumieren einen Teil davon", "Händler setzen mehr um und stellen ein"],
    explain: "Jede Runde ist kleiner als die vorige, weil ein Teil gespart, versteuert oder für Importe ausgegeben wird. Die Summe aller Runden ergibt den Multiplikatoreffekt." },
  { id: "vma-083", cat: "vwl", topic: "Fiskalpolitik", type: "quiz", emoji: "🔮", level: 3,
    q: "Was besagt die Ricardianische Äquivalenz?",
    options: ["Staatsausgaben haben immer einen Multiplikator von genau 1", "Wechselkurse gleichen Preisunterschiede aus", "Schuldenfinanzierte Steuersenkungen verpuffen, weil Bürger künftige Steuern einplanen und sparen", "Steuern und Zölle wirken auf Preise gleich"],
    answer: 2,
    explain: "Rationale Haushalte erkennen: Heutige Schulden sind morgige Steuern – also sparen sie die Entlastung. In der Realität gilt die These nur teilweise, weil viele Haushalte kurzfristig denken oder kein finanzielles Polster haben." },

  // ───────── Staatsschulden ─────────
  { id: "vma-084", cat: "vwl", topic: "Staatsschulden", type: "number", emoji: "🇩🇪", level: 1,
    value: "≈ 63 %", label: "Schuldenquote Deutschlands (Stand 2024)",
    text: "Staatsschulden im Verhältnis zum BIP – rund 2,7 Bio. €. Deutlich weniger als Frankreich (über 110 %) oder Italien (rund 135 %), aber leicht über der Maastricht-Grenze von 60 %.",
    more: "Die Quote kann sogar ohne Tilgung sinken: Wächst das nominale BIP schneller als die Schulden, schrumpft der Bruch. So fiel Deutschlands Quote von über 80 % (2010) auf unter 60 % (2019)." },
  { id: "vma-085", cat: "vwl", topic: "Staatsschulden", type: "quiz", emoji: "📏", level: 1,
    q: "Welche Obergrenzen setzen die Maastricht-Kriterien für Euro-Staaten?",
    options: ["3 % Schuldenquote, 60 % Defizit", "2 % Defizit, 50 % Schuldenquote", "0,35 % Defizit, 60 % Schuldenquote", "60 % Schuldenquote, 3 % Defizit"],
    answer: 3,
    explain: "Schulden max. 60 % des BIP, jährliches Defizit max. 3 % des BIP. Merkhilfe: Der große Bestand hat die große Zahl, der jährliche Zufluss die kleine. Viele Staaten reißen beide Grenzen regelmäßig." },
  { id: "vma-086", cat: "vwl", topic: "Staatsschulden", type: "number", emoji: "🗾", level: 2,
    value: "> 230 %", label: "Schuldenquote Japans (Stand 2024)",
    text: "Die höchste unter den großen Industrieländern – trotzdem keine Staatspleite. Die Schulden lauten auf Yen, liegen überwiegend bei Inländern, und die Bank of Japan hält rund die Hälfte der Staatsanleihen.",
    more: "Lehre: Nicht nur die Höhe zählt, sondern Gläubigerstruktur, Währung und Zinsniveau. Ein Euro-Staat verschuldet sich in einer Währung, die er nicht selbst drucken kann – das machte Griechenland 2010 so verwundbar." },
  { id: "vma-087", cat: "vwl", topic: "Staatsschulden", type: "whatif", emoji: "📈", level: 2,
    q: "Was passiert, wenn die Zinsen auf Staatsanleihen dauerhaft steigen?",
    steps: ["Neue Kredite werden teurer", "Alte Anleihen werden teurer refinanziert", "Zinsausgaben wachsen im Haushalt", "Sie verdrängen Investitionen und Soziales"],
    text: "Die Zinsausgaben des Bundes stiegen von unter 5 Mrd. € (2021) auf über 30 Mrd. € (2023/24). Weil Anleihen erst nach und nach fällig werden, wirkt eine Zinswende auf den Haushalt mit jahrelanger Verzögerung – aber stetig." },
  { id: "vma-088", cat: "vwl", topic: "Staatsschulden", type: "flashcard", emoji: "🧮", level: 3,
    term: "r < g (Schuldentragfähigkeit)",
    def: "Liegt der Zins auf Staatsschulden (r) unter dem nominalen Wachstum (g), sinkt die Schuldenquote auch bei leichten Defiziten. Ist r > g, braucht der Staat Primärüberschüsse (Haushalt ohne Zinsen im Plus).",
    example: "Nach dem Zweiten Weltkrieg bauten USA und Großbritannien hohe Schuldenquoten vor allem über Wachstum und Inflation ab – nicht durch Tilgung." },
  { id: "vma-089", cat: "vwl", topic: "Staatsschulden", type: "truefalse", emoji: "♾️", level: 1,
    q: "Ein Staat muss seine Schulden irgendwann vollständig zurückzahlen – wie ein Privathaushalt.",
    answer: false,
    explain: "Staaten ersetzen fällige Anleihen meist durch neue (Revolvieren). Entscheidend ist, dass Anleger der Zahlungsfähigkeit vertrauen und die Schuldenquote tragfähig bleibt. Ein Staat „stirbt“ nicht und hat ein Steuerrecht." },
  { id: "vma-090", cat: "vwl", topic: "Staatsschulden", type: "quiz", emoji: "🛁", level: 2,
    q: "Ein Staat hat ein Defizit von 3 %. Was bedeutet das?",
    options: ["Seine Schulden betragen 3 % des BIP", "Er nimmt in diesem Jahr neue Schulden von 3 % des BIP auf", "Seine Zinsen betragen 3 %", "Seine Steuereinnahmen sinken um 3 %"],
    answer: 1,
    explain: "**Defizit** = Stromgröße (Neuverschuldung pro Jahr), **Schulden** = Bestandsgröße. Bild: Das Defizit ist der Wasserzulauf, die Schulden sind der Wasserstand in der Badewanne." },
  { id: "vma-091", cat: "vwl", topic: "Staatsschulden", type: "order", emoji: "🧨", level: 3,
    q: "Sortiere den typischen Verlauf einer Staatsschuldenkrise.",
    items: ["Zweifel an der Zahlungsfähigkeit kommen auf", "Renditen der Staatsanleihen steigen", "Refinanzierung wird unbezahlbar", "Hilfsprogramm mit Auflagen oder Schuldenschnitt"],
    explain: "Steigende Zinsen machen die Lage objektiv schlechter – Zweifel können sich so selbst erfüllen. Das ist der Grund für Rettungsschirme wie den ESM und für Zentralbank-Interventionen." },

  // ───────── Wechselkurse ─────────
  { id: "vma-092", cat: "vwl", topic: "Wechselkurse", type: "whatif", emoji: "💪", level: 1,
    q: "Was passiert, wenn der Euro stark aufwertet?",
    steps: ["Europäische Waren im Ausland teurer", "Exporte sinken, vor allem Industrie", "Importe und USA-Urlaub werden billiger", "Inflation sinkt tendenziell", "Exportlastiges Deutschland leidet"],
    text: "Eine Aufwertung wirkt wie eine leichte Zinserhöhung: Sie dämpft Nachfrage und Preise. Für Exporteure schrumpfen die Margen – viele sichern sich deshalb über Devisentermingeschäfte oder Produktion im Ausland ab." },
  { id: "vma-093", cat: "vwl", topic: "Wechselkurse", type: "flashcard", emoji: "💱", level: 1,
    term: "Aufwertung",
    def: "Die eigene Währung gewinnt an Wert gegenüber einer anderen. Steigt der Kurs von 1,10 auf 1,20 Dollar je Euro, hat der Euro aufgewertet.",
    example: "Merkhilfe: Aufwertung = Auslandsurlaub billiger, Export schwerer. Abwertung = umgekehrt." },
  { id: "vma-094", cat: "vwl", topic: "Wechselkurse", type: "quiz", emoji: "⛽", level: 2,
    q: "Der Euro fällt von 1,20 auf 1,00 Dollar. Was wird für Menschen im Euroraum teurer?",
    options: ["In Dollar abgerechnetes Rohöl", "Urlaub in Italien", "Deutsche Autos für US-Kunden", "Mieten in Deutschland"],
    answer: 0,
    explain: "Für ein Barrel zu 80 $ braucht man statt 67 € nun 80 € – **importierte Inflation**. Deutsche Autos werden für Amerikaner dagegen billiger: Abwertung hilft Exporteuren." },
  { id: "vma-095", cat: "vwl", topic: "Wechselkurse", type: "fact", emoji: "📒", level: 2,
    title: "Zahlungsbilanz: Leistungsbilanz und Kapitalbilanz",
    text: "Die Zahlungsbilanz erfasst alle Transaktionen mit dem Ausland. Die **Leistungsbilanz** umfasst Güter, Dienstleistungen, Einkommen und Übertragungen. Ein Überschuss dort heißt spiegelbildlich: Das Land baut Forderungen gegenüber dem Ausland auf.",
    more: "Wer mehr verkauft als kauft, muss die Differenz irgendwo anlegen – als Kredit, Wertpapier oder Firmenbeteiligung im Ausland. Deutschland hat so über Jahrzehnte ein Netto-Auslandsvermögen von mehreren Billionen Euro aufgebaut." },
  { id: "vma-096", cat: "vwl", topic: "Wechselkurse", type: "number", emoji: "⚖️", level: 2,
    value: "5–6 %", label: "Leistungsbilanzüberschuss DE in % des BIP (2023/24)",
    text: "Einer der größten Überschüsse der Welt in Euro. Den Höhepunkt gab es 2015/16 mit über 8 % des BIP. Die EU-Kommission wertet dauerhafte Überschüsse über 6 % als Ungleichgewicht.",
    more: "Kritik (USA, IWF): Deutschland spare zu viel und investiere zu wenig im Inland. Verteidigung: Eine alternde Gesellschaft spart sinnvollerweise für die Rente, und Überschüsse spiegeln wettbewerbsfähige Produkte. Wahrheit: Überschuss = Ersparnis > Investitionen." },
  { id: "vma-097", cat: "vwl", topic: "Wechselkurse", type: "truefalse", emoji: "🏆", level: 2,
    q: "Ein Leistungsbilanzüberschuss ist immer ein Zeichen wirtschaftlicher Stärke.",
    answer: false,
    explain: "Er bedeutet auch: Im Inland wird weniger investiert als gespart. Das Geld fließt ins Ausland – und Auslandsanlagen können an Wert verlieren (z. B. US-Immobilienpapiere 2008). Zudem brauchen Überschüsse Defizitländer als Gegenpart, was politische Konflikte schürt." },
  { id: "vma-098", cat: "vwl", topic: "Wechselkurse", type: "quiz", emoji: "🍔", level: 3,
    q: "Was besagt die Kaufkraftparität?",
    options: ["Wechselkurse passen sich langfristig so an, dass gleiche Güter überall gleich viel kosten", "Zinsen sind weltweit gleich hoch", "Löhne gleichen sich durch Handel vollständig an", "Zentralbanken fixieren Wechselkurse"],
    answer: 0,
    explain: "Bekannte Illustration: der **Big-Mac-Index** des Economist. Kurzfristig weichen Wechselkurse oft stark ab (Kapitalströme, Zinsen, Stimmung); langfristig wirkt die Kaufkraftparität wie ein Gummiband." },
  { id: "vma-099", cat: "vwl", topic: "Wechselkurse", type: "event", emoji: "🇨🇭", level: 3,
    year: "2015", title: "Schweizer Nationalbank gibt den Euro-Mindestkurs auf",
    text: "Seit 2011 hatte die SNB den Franken bei 1,20 je Euro gedeckelt und dafür unbegrenzt Euro gekauft. Am 15. Januar 2015 gab sie überraschend auf – der Franken schoss binnen Minuten um bis zu 30 % nach oben.",
    more: "Lehre: Wer eine Aufwertung verhindern will, muss eigene Währung schaffen und Devisen kaufen – die SNB-Bilanz blähte sich enorm auf. Exportindustrie und Tourismus der Schweiz litten, Kreditnehmer mit Franken-Krediten in Osteuropa ebenfalls." },

  // ───────── Außenhandel ─────────
  { id: "vma-100", cat: "vwl", topic: "Außenhandel", type: "whatif", emoji: "🚗", level: 1,
    q: "Was passiert, wenn die USA 25 % Zölle auf Autos aus der EU erheben?",
    steps: ["EU-Autos werden in den USA teurer", "Absatz deutscher Hersteller sinkt", "Produktion wandert teils in die USA", "US-Kunden zahlen mehr, haben weniger Wahl", "EU erwägt Gegenzölle"],
    text: "Den Zoll zahlt formal der Importeur; die Last teilen sich Kunden und Hersteller. 2025 verhängten die USA tatsächlich 25 % Autozölle; nach dem EU-US-Abkommen vom Sommer 2025 sanken sie für EU-Autos auf 15 % – immer noch ein Vielfaches der vorherigen 2,5 %." },
  { id: "vma-101", cat: "vwl", topic: "Außenhandel", type: "fact", emoji: "🍷", level: 1,
    title: "Komparative Vorteile: Warum Handel beiden nützt",
    text: "David Ricardo (1817): Selbst wenn ein Land alles effizienter herstellt, lohnt sich Handel – sofern sich jedes Land auf das spezialisiert, was es **relativ** am besten kann. Beispiel: Portugal Wein, England Tuch.",
    more: "Merkhilfe: Eine Anwältin tippt schneller als ihr Assistent – lässt ihn trotzdem tippen, weil ihre Stunde in der Beratung mehr wert ist. Entscheidend sind Opportunitätskosten, nicht absolute Kosten." },
  { id: "vma-102", cat: "vwl", topic: "Außenhandel", type: "truefalse", emoji: "🤝", level: 2,
    q: "Von Freihandel profitieren innerhalb eines Landes alle Menschen.",
    answer: false,
    explain: "Insgesamt steigt der Wohlstand, aber es gibt Verlierer – etwa Industriebeschäftigte in Regionen, die mit Importen konkurrieren (der „China-Schock“ in den USA nach 2001). Ohne Ausgleich wächst die Unterstützung für Protektionismus." },
  { id: "vma-103", cat: "vwl", topic: "Außenhandel", type: "quiz", emoji: "📦", level: 1,
    q: "Welche Warengruppe exportiert Deutschland wertmäßig am meisten?",
    options: ["Kraftfahrzeuge und Kfz-Teile", "Maschinen", "Lebensmittel", "Textilien"],
    answer: 0,
    explain: "Autos und Teile führen vor Maschinen und chemischen Erzeugnissen. Diese Konzentration macht Deutschland verwundbar – gegenüber Autozöllen, dem Wandel zum E-Auto und Konkurrenz aus China." },
  { id: "vma-104", cat: "vwl", topic: "Außenhandel", type: "number", emoji: "🚢", level: 1,
    value: "≈ 45 %", label: "Anteil der Exporte am BIP in Deutschland (Stand 2024)",
    text: "Waren und Dienstleistungen zusammen – zum Vergleich: In den USA sind es nur rund 11 %. Fast jeder vierte Arbeitsplatz in Deutschland hängt direkt oder indirekt am Export.",
    more: "Achtung: Exportquote ≠ Wertschöpfungsanteil, denn Exporte enthalten importierte Vorprodukte. Die hohe Quote ist Stärke (Weltmärkte) und Schwäche zugleich: Handelskonflikte und schwache Weltkonjunktur treffen Deutschland überdurchschnittlich." },
  { id: "vma-105", cat: "vwl", topic: "Außenhandel", type: "fact", emoji: "🇨🇳", level: 2,
    title: "Abhängigkeit von China",
    text: "China war von 2016 bis 2023 Deutschlands wichtigster Handelspartner; 2024 lagen wieder die USA vorn. Heikel sind weniger die Mengen als Engpässe bei seltenen Erden, Batterien, Solarmodulen und Arzneiwirkstoffen.",
    more: "Strategie „De-Risking“ statt „Decoupling“: Lieferketten diversifizieren, ohne den Handel zu kappen. Zugleich wird China vom Kunden zum Konkurrenten – etwa bei E-Autos und Maschinen; deutsche Exporte nach China sinken seit 2022." },
  { id: "vma-106", cat: "vwl", topic: "Außenhandel", type: "whatif", emoji: "🧲", level: 2,
    q: "Was passiert, wenn China den Export seltener Erden stoppt?",
    steps: ["Magnete für E-Motoren und Windräder fehlen", "Produktionsstopps bei Autozulieferern", "Preise für Ersatzquellen steigen stark", "Politik fördert Alternativen und Lager"],
    text: "China dominiert die Verarbeitung seltener Erden (rund 90 % weltweit). 2025 führte Peking Exportkontrollen ein, die bei europäischen Autozulieferern kurzzeitig Engpässe auslösten – ein Lehrstück für Abhängigkeiten in Lieferketten." },
  { id: "vma-107", cat: "vwl", topic: "Außenhandel", type: "quiz", emoji: "🧾", level: 2,
    q: "Wer trug laut Studien den Großteil der US-Zölle von 2018/19 auf chinesische Waren?",
    options: ["Chinesische Exporteure fast vollständig", "US-Importeure und Verbraucher", "Die Welthandelsorganisation", "Niemand – die Preise blieben gleich"],
    answer: 1,
    explain: "Mehrere Studien fanden eine fast vollständige Überwälzung auf US-Preise. Zölle wirken wie eine Steuer auf die eigenen Importeure und Kunden – auch wenn sie politisch als Strafe für das Ausland verkauft werden." },
  { id: "vma-108", cat: "vwl", topic: "Außenhandel", type: "whatif", emoji: "⚔️", level: 3,
    q: "Was passiert, wenn ein Handelskrieg mit Gegenzöllen eskaliert?",
    steps: ["Beide Seiten verteuern Importe", "Lieferketten werden teuer umgebaut", "Unsicherheit bremst Investitionen", "Welthandel und Wachstum sinken", "Exportländer wie DE trifft es stark"],
    text: "Historische Warnung: Der US-Zoll Smoot-Hawley (1930) löste Vergeltung aus; der Wert des Welthandels brach bis 1933 um rund zwei Drittel ein und verschärfte die Weltwirtschaftskrise. Daraus entstanden nach 1945 GATT und später die WTO." },
  { id: "vma-109", cat: "vwl", topic: "Außenhandel", type: "flashcard", emoji: "🚧", level: 2,
    term: "Protektionismus",
    def: "Schutz heimischer Anbieter vor Importkonkurrenz durch **tarifäre** (Zölle) und **nicht-tarifäre** Hemmnisse (Quoten, Subventionen, Normen, Bürokratie, Local-Content-Regeln).",
    example: "Klassisches Argument: junge Industrien schützen, bis sie wettbewerbsfähig sind („Infant Industry“). Risiken: Gegenmaßnahmen, höhere Preise, träge geschützte Branchen." },
  { id: "vma-110", cat: "vwl", topic: "Außenhandel", type: "truefalse", emoji: "🌍", level: 1,
    q: "Ein Zoll wird vom exportierenden Ausland an den Staat des Importlandes bezahlt.",
    answer: false,
    explain: "Den Zoll überweist der **Importeur** im eigenen Land an den eigenen Zoll. Ob er ihn an Kunden weitergibt oder der ausländische Hersteller die Preise senkt, entscheidet sich am Markt – meist zahlen Inländer einen großen Teil." },

  // ───────── Euro & Eurokrise ─────────
  { id: "vma-111", cat: "vwl", topic: "Euro & Eurokrise", type: "order", emoji: "🇪🇺", level: 1,
    q: "Sortiere die Etappen der europäischen Wirtschaftsintegration.",
    items: ["Montanunion (EGKS), 1951", "Römische Verträge: EWG, 1957", "EU-Binnenmarkt, 1993", "Euro als Buchgeld, 1999", "Euro-Bargeld, 2002"],
    explain: "Von Kohle und Stahl über den Gemeinsamen Markt zur Währungsunion. 2026 hat der Euroraum 21 Mitglieder (zuletzt Kroatien 2023 und Bulgarien 2026)." },
  { id: "vma-112", cat: "vwl", topic: "Euro & Eurokrise", type: "event", emoji: "🇬🇷", level: 2,
    year: "2010", title: "Griechenland braucht das erste Rettungspaket",
    text: "Ende 2009 wurde bekannt, dass Griechenlands Defizit weit höher war als gemeldet (über 12 % statt rund 4 % des BIP). Die Zinsen schossen hoch; im Mai 2010 sagten Euro-Staaten und IWF 110 Mrd. € Hilfe zu.",
    more: "Es folgten zwei weitere Programme (2012 mit Schuldenschnitt für private Gläubiger, 2015). Gegenleistung: harte Spar- und Reformauflagen – das BIP schrumpfte um rund ein Viertel. Aus der Krise entstanden die Rettungsschirme EFSF und ESM." },
  { id: "vma-113", cat: "vwl", topic: "Euro & Eurokrise", type: "event", emoji: "🎤", level: 2,
    year: "2012", title: "Draghi: „Whatever it takes“",
    text: "Am 26. Juli 2012 sagte EZB-Präsident Mario Draghi in London, die EZB werde im Rahmen ihres Mandats alles Nötige tun, um den Euro zu erhalten – „and believe me, it will be enough“. Die Renditen Spaniens und Italiens fielen deutlich.",
    more: "Das zugehörige Programm **OMT** (unbegrenzte Anleihekäufe für Staaten unter ESM-Auflagen) wurde nie eingesetzt – die glaubwürdige Ankündigung reichte. Ein Lehrstück für die Macht von Erwartungen." },
  { id: "vma-114", cat: "vwl", topic: "Euro & Eurokrise", type: "whatif", emoji: "🔒", level: 2,
    q: "Was passiert, wenn ein Euro-Land zu teuer geworden ist, aber nicht abwerten kann?",
    steps: ["Exporte stagnieren, Importe steigen", "Leistungsbilanzdefizit und Schulden wachsen", "Abwertung als Ventil fehlt", "Löhne und Preise müssen real sinken", "Lange Phase hoher Arbeitslosigkeit"],
    text: "**Interne Abwertung** – der schmerzhafte Weg Griechenlands, Spaniens und Portugals nach 2010. Die Theorie des optimalen Währungsraums (Mundell) nennt Ausgleichsmechanismen: mobile Arbeitskräfte, flexible Löhne, gemeinsame Fiskaltransfers – im Euroraum alle schwach ausgeprägt." },
  { id: "vma-115", cat: "vwl", topic: "Euro & Eurokrise", type: "truefalse", emoji: "☂️", level: 3,
    q: "Der Europäische Stabilitätsmechanismus (ESM) ist ein dauerhafter Rettungsschirm mit 500 Mrd. € Darlehenskapazität.",
    answer: true,
    explain: "Der ESM nahm 2012 die Arbeit auf und löste den befristeten EFSF ab. Er vergibt Kredite an Euro-Staaten nur gegen Auflagen und finanziert sich am Kapitalmarkt, abgesichert durch Kapital der Mitgliedstaaten." },
  { id: "vma-116", cat: "vwl", topic: "Euro & Eurokrise", type: "quiz", emoji: "♻️", level: 2,
    q: "Was war der „Teufelskreis“ (Doom Loop) der Eurokrise?",
    options: ["Banken hielten heimische Staatsanleihen – fiel deren Wert, wankten die Banken, und Bankrettungen belasteten wieder den Staat", "Steigende Löhne trieben die Preise und umgekehrt", "Zölle führten zu Gegenzöllen", "Ein höherer Ölpreis schwächte den Euro"],
    answer: 0,
    explain: "Staat und Banken zogen sich gegenseitig herunter. Antwort der EU: die **Bankenunion** – seit 2014 beaufsichtigt die EZB die großen Banken direkt, dazu kommen gemeinsame Abwicklungsregeln." },

  // ───────── Finanzkrise 2008 ─────────
  { id: "vma-117", cat: "vwl", topic: "Finanzkrise 2008", type: "event", emoji: "🏚️", level: 1,
    year: "2008", title: "Lehman-Pleite: Die Finanzkrise eskaliert",
    text: "Am 15. September 2008 meldete die US-Investmentbank Insolvenz an – die größte Pleite der US-Geschichte. Die Finanzkrise eskalierte weltweit: Banken liehen einander kein Geld mehr, Börsen stürzten ab.",
    more: "Wurzeln: US-Immobilienblase, Kredite an Schuldner mit schwacher Bonität (Subprime), verbrieft in komplexe Wertpapiere, dazu hohe Verschuldung der Banken. Weil Washington Lehman fallen ließ, rettete man danach fast alle großen Häuser – „too big to fail“." },
  { id: "vma-118", cat: "vwl", topic: "Finanzkrise 2008", type: "order", emoji: "🧱", level: 2,
    q: "Sortiere die Kette der Finanzkrise 2007–2009.",
    items: ["Immobilienboom mit lockeren Subprime-Krediten", "Kredite werden verbrieft und weltweit verkauft", "Hauspreise fallen, Kredite platzen", "Banken misstrauen sich, Lehman bricht zusammen", "Weltweite Rezession 2009"],
    explain: "Die Verbriefung verteilte US-Hypothekenrisiken über den Globus – auch zu deutschen Landesbanken und der IKB. Niemand wusste mehr genau, wer welche Risiken hielt, daher das Misstrauen." },
  { id: "vma-119", cat: "vwl", topic: "Finanzkrise 2008", type: "number", emoji: "📉", level: 1,
    value: "−5,7 %", label: "Einbruch des realen BIP in Deutschland 2009",
    text: "Der schwerste Rückgang der Nachkriegsgeschichte – die Exporte brachen ein. Trotzdem stieg die Arbeitslosigkeit kaum: Kurzarbeit und Arbeitszeitkonten verhinderten Massenentlassungen (das „deutsche Jobwunder“).",
    more: "Dazu kamen Konjunkturpakete, etwa die Abwrackprämie von 2.500 € für Altautos. 2010 wuchs die Wirtschaft schon wieder kräftig. Zum Vergleich Corona-Jahr 2020: rund −4 %." },
  { id: "vma-120", cat: "vwl", topic: "Finanzkrise 2008", type: "whatif", emoji: "🏦", level: 2,
    q: "Was passiert, wenn eine systemrelevante Bank pleitegeht?",
    steps: ["Geschäftspartner verlieren Forderungen", "Banken leihen einander nichts mehr", "Firmenkredite versiegen", "Panik an den Börsen", "Staat rettet – oder tiefe Rezession"],
    text: "Darum gelten seit der Krise strengere Regeln: mehr Eigenkapital (Basel III), Abwicklungspläne und **Bail-in** – zuerst haften Eigentümer und Gläubiger, erst dann der Steuerzahler." },
  { id: "vma-121", cat: "vwl", topic: "Finanzkrise 2008", type: "flashcard", emoji: "🎲", level: 2,
    term: "Moral Hazard im Bankensystem",
    def: "Fehlanreiz: Wer erwartet, im Notfall gerettet zu werden, geht höhere Risiken ein. Gewinne bleiben privat, Verluste werden sozialisiert.",
    example: "„Too big to fail“-Banken. Gegenmittel: höhere Eigenkapitalpflichten und die EU-Bail-in-Regeln seit 2016." },

  // ───────── Ölkrise 1973 ─────────
  { id: "vma-122", cat: "vwl", topic: "Ölkrise 1973", type: "event", emoji: "⛽", level: 1,
    year: "1973", title: "Erste Ölkrise",
    text: "Nach dem Jom-Kippur-Krieg drosselten arabische Ölstaaten die Förderung und verhängten Embargos gegen westliche Länder. Der Ölpreis vervierfachte sich binnen Monaten. In der Bundesrepublik gab es im Herbst 1973 autofreie Sonntage.",
    more: "Folgen: Stagflation und das Ende der Vollbeschäftigung des Wirtschaftswunders – 1975 gab es erstmals seit den 1950ern über 1 Mio. Arbeitslose. Die zweite Ölkrise folgte 1979/80 nach der Iranischen Revolution. Langfristig: Energiesparen, Atomkraft, strategische Ölreserven." },
  { id: "vma-123", cat: "vwl", topic: "Ölkrise 1973", type: "whatif", emoji: "🛢️", level: 1,
    q: "Was passiert, wenn sich der Ölpreis verdoppelt?",
    steps: ["Sprit, Heizöl und Transport teurer", "Inflation steigt sofort", "Kaufkraft der Haushalte sinkt", "Firmenkosten steigen, Gewinne sinken", "Geld fließt zu den Ölexporteuren"],
    text: "Ein klassischer **Angebotsschock**: höhere Preise und weniger Produktion zugleich. Für Ölimporteure wie Deutschland verschlechtern sich die Terms of Trade – man muss mehr exportieren, um dieselbe Menge Öl zu bezahlen. Die Zentralbank steht vor dem Stagflations-Dilemma." },
  { id: "vma-124", cat: "vwl", topic: "Ölkrise 1973", type: "quiz", emoji: "🧯", level: 3,
    q: "Warum führten die Ölkrisen der 1970er zu Stagflation statt „nur“ zu Inflation?",
    options: ["Weil die Zentralbanken Geld vernichteten", "Weil höhere Energiekosten die Produktion verteuerten und zugleich Kaufkraft abzogen", "Weil die Löhne stark fielen", "Weil die Exporte boomten"],
    answer: 1,
    explain: "Ein Angebotsschock verschiebt die Angebotskurve nach links: Preise rauf, Produktion runter. Hinzu kamen Lohnrunden, die die Inflation weitertrugen, und eine Geldpolitik, die anfangs nachgab." },

  // ───────── Hyperinflation 1923 ─────────
  { id: "vma-125", cat: "vwl", topic: "Hyperinflation 1923", type: "event", emoji: "💴", level: 1,
    year: "1923", title: "Hyperinflation in Deutschland",
    text: "Im November 1923 kostete 1 US-Dollar 4,2 Billionen Mark. Löhne wurden täglich ausgezahlt und sofort ausgegeben, Ersparnisse waren wertlos, Preise änderten sich mehrmals am Tag.",
    more: "Ursachen: Kriegsfinanzierung über die Notenpresse, Reparationen und die Ruhrbesetzung 1923 – der Staat bezahlte den passiven Widerstand mit gedrucktem Geld. Ende mit der Rentenmark (15.11.1923): 1 Rentenmark = 1 Billion Papiermark. Prägt die deutsche Inflationsangst bis heute." },
  { id: "vma-126", cat: "vwl", topic: "Hyperinflation 1923", type: "truefalse", emoji: "🏚️", level: 2,
    q: "Von der Hyperinflation 1923 profitierten Schuldner – auch der Staat.",
    answer: true,
    explain: "Schulden in Mark wurden real wertlos: Wer eine Hypothek hatte, tilgte sie mit Spielgeld, der Staat wurde seine inneren Kriegsschulden los. Die großen Verlierer waren Sparer und der Mittelstand – mit schweren politischen Folgen für die Weimarer Republik." },
  { id: "vma-127", cat: "vwl", topic: "Hyperinflation 1923", type: "order", emoji: "📅", level: 3,
    q: "Sortiere die Wirtschaftskrisen der Weimarer Republik chronologisch.",
    items: ["Hyperinflation und Rentenmark", "Dawes-Plan ordnet die Reparationen", "Börsencrash in New York", "Brünings Sparpolitik, über 6 Mio. Arbeitslose"],
    explain: "1923 → 1924 → 1929 → 1930–32. Wichtig für das deutsche Gedächtnis: Nicht nur die Inflation 1923, sondern auch die Deflation und Massenarbeitslosigkeit der frühen 1930er bereiteten den Boden für den Aufstieg der NSDAP." },

  // ───────── Deutschland in Zahlen ─────────
  { id: "vma-128", cat: "vwl", topic: "Deutschland in Zahlen", type: "number", emoji: "💶", level: 1,
    value: "≈ 4,3 Bio. €", label: "nominales BIP Deutschlands (2024)",
    text: "Drittgrößte Volkswirtschaft der Welt nach den USA und China (gemessen in US-Dollar). Pro Kopf sind das gut 50.000 € im Jahr.",
    more: "Deutschland überholte 2023 Japan – vor allem wegen des schwachen Yen, nicht wegen eigener Stärke: Real stagnierte die deutsche Wirtschaft 2023 und 2024. Rangfolgen in Dollar schwanken mit den Wechselkursen." },
  { id: "vma-129", cat: "vwl", topic: "Deutschland in Zahlen", type: "number", emoji: "👨‍👩‍👧", level: 1,
    value: "≈ 83,5 Mio.", label: "Einwohner Deutschlands (Stand 2024)",
    text: "Seit Jahrzehnten sterben mehr Menschen, als geboren werden. Die Bevölkerung wächst nur durch Zuwanderung. Die Geburtenrate lag 2023/24 bei rund 1,35 Kindern je Frau.",
    more: "Für eine stabile Bevölkerung ohne Zuwanderung wären rund 2,1 Kinder je Frau nötig. Makroökonomisch heißt das: weniger Erwerbstätige, mehr Rentner, steigender Druck auf Sozialsysteme und Arbeitsmarkt." },
  { id: "vma-130", cat: "vwl", topic: "Deutschland in Zahlen", type: "number", emoji: "👷", level: 2,
    value: "≈ 46 Mio.", label: "Erwerbstätige in Deutschland (2024, Rekord)",
    text: "So viele wie nie zuvor – obwohl die Wirtschaft stagniert. Gründe: Zuwanderung sowie mehr erwerbstätige Frauen und Ältere. Aber: Die Arbeitszeit pro Kopf ist vergleichsweise niedrig, weil viele Teilzeit arbeiten.",
    more: "Für das BIP zählt das **Arbeitsvolumen** (Personen × Stunden). Es wächst kaum, weil der Rekord bei den Köpfen durch mehr Teilzeit ausgeglichen wird. Mit dem Ruhestand der Babyboomer dürfte die Zahl der Erwerbstätigen künftig sinken." },
  { id: "vma-131", cat: "vwl", topic: "Deutschland in Zahlen", type: "quiz", emoji: "🏭", level: 2,
    q: "Welchen Anteil an der Bruttowertschöpfung hat das Verarbeitende Gewerbe in Deutschland ungefähr?",
    options: ["Rund 5 %", "Rund 20 %", "Rund 40 %", "Rund 60 %"],
    answer: 1,
    explain: "Etwa ein Fünftel – deutlich mehr als in den USA, Frankreich oder Großbritannien (jeweils um 10 %). Rund 70 % entfallen auf Dienstleistungen. Der hohe Industrieanteil erklärt, warum Energiepreise und Welthandel Deutschland so stark treffen." },
  { id: "vma-132", cat: "vwl", topic: "Deutschland in Zahlen", type: "truefalse", emoji: "🥇", level: 1,
    q: "Deutschland ist die größte Volkswirtschaft der Europäischen Union.",
    answer: true,
    explain: "Deutschland erwirtschaftet knapp ein Viertel des EU-BIP, vor Frankreich und Italien. Deshalb strahlt eine deutsche Rezession auf ganz Europa aus – vor allem auf eng verflochtene Zulieferländer wie Tschechien, Österreich oder die Niederlande." },

  // ───────── Demografie & Rente ─────────
  { id: "vma-133", cat: "vwl", topic: "Demografie & Rente", type: "fact", emoji: "👵", level: 1,
    title: "Die gesetzliche Rente ist umlagefinanziert",
    text: "Die heutigen Beitragszahler finanzieren die heutigen Renten – ein Kapitalstock wird nicht angespart. Der Beitragssatz beträgt 18,6 % des Bruttolohns (Stand 2025), je zur Hälfte von Arbeitgeber und Beschäftigten.",
    more: "Zusätzlich schießt der Bund jährlich über 100 Mrd. € aus Steuermitteln zu – einer der größten Posten im Bundeshaushalt. Kernproblem: Kommen auf einen Rentner weniger Beitragszahler, müssen Beiträge oder Steuerzuschüsse steigen oder die Renten relativ sinken." },
  { id: "vma-134", cat: "vwl", topic: "Demografie & Rente", type: "whatif", emoji: "🎂", level: 1,
    q: "Was passiert makroökonomisch, wenn die Babyboomer-Jahrgänge den Arbeitsmarkt verlassen?",
    steps: ["Viele Beitragszahler werden Rentner", "Weniger Zahler je Rentner", "Druck auf Beiträge, Niveau, Zuschuss", "Fachkräfte fehlen am Arbeitsmarkt", "Nachfrage verschiebt sich zu Pflege"],
    text: "Die geburtenstarken Jahrgänge (etwa 1955–1969, Spitze 1964 mit rund 1,4 Mio. Geburten) gehen bis Mitte der 2030er in Rente. Der Altenquotient – über 65-Jährige je 100 Personen im Erwerbsalter – steigt deutlich." },
  { id: "vma-135", cat: "vwl", topic: "Demografie & Rente", type: "quiz", emoji: "🧓", level: 2,
    q: "Welche Maßnahme entlastet die gesetzliche Rentenversicherung NICHT?",
    options: ["Ein höheres Renteneintrittsalter", "Frühverrentung ohne Abschläge ausweiten", "Mehr Zuwanderung in sozialversicherte Jobs", "Höhere Erwerbstätigkeit von Frauen"],
    answer: 1,
    explain: "Frühere Rente bedeutet weniger Beitragsjahre und mehr Rentenjahre – doppelte Belastung. Alle anderen Maßnahmen erhöhen die Zahl der Beitragszahler oder verkürzen die Bezugsdauer." },
  { id: "vma-136", cat: "vwl", topic: "Demografie & Rente", type: "truefalse", emoji: "📊", level: 3,
    q: "Eine kapitalgedeckte Rente ist vom demografischen Wandel völlig unabhängig.",
    answer: false,
    explain: "Auch angespartes Kapital muss im Alter in Güter getauscht werden, die dann Erwerbstätige herstellen (**Mackenroth-These**). Verkaufen viele Rentner gleichzeitig Wertpapiere, können die Preise fallen. Breite internationale Streuung mildert das Problem." },
  { id: "vma-137", cat: "vwl", topic: "Demografie & Rente", type: "number", emoji: "📐", level: 2,
    value: "48 %", label: "Haltelinie für das gesetzliche Rentenniveau",
    text: "Das Rentenniveau setzt eine Standardrente (45 Beitragsjahre, Durchschnittsverdienst) ins Verhältnis zum Durchschnittslohn, jeweils nach Sozialabgaben, vor Steuern. Es ist keine Aussage darüber, wie viel Prozent des eigenen Lohns man bekommt.",
    more: "Die Haltelinie galt bis 2025; die Koalition aus Union und SPD wollte sie bis 2031 verlängern (Stand 2025). Ohne Haltelinie würde das Niveau mit der Alterung sinken – mit ihr steigen Beiträge oder Steuerzuschüsse." },

  // ───────── Energie & Industrie ─────────
  { id: "vma-138", cat: "vwl", topic: "Energie & Industrie", type: "whatif", emoji: "🔥", level: 2,
    q: "Was passiert, wenn russisches Pipelinegas plötzlich ausfällt?",
    steps: ["Gas-Großhandelspreise explodieren", "Strom wird teurer (Gas setzt oft den Preis)", "Energieintensive Industrie drosselt", "Inflation steigt, Kaufkraft sinkt", "Staat greift ein: Preisbremsen, LNG"],
    text: "So geschah es 2022: Der Großhandelspreis für Gas stieg zeitweise auf über 300 €/MWh – mehr als das Zehnfache früherer Werte. Russland hatte zuvor rund die Hälfte des deutschen Gases geliefert; Ersatz kam aus Norwegen, den Niederlanden und per Flüssiggas (LNG)." },
  { id: "vma-139", cat: "vwl", topic: "Energie & Industrie", type: "flashcard", emoji: "🪜", level: 3,
    term: "Merit-Order",
    def: "Preisbildung an der Strombörse: Kraftwerke kommen nach ihren Grenzkosten zum Zug – erst Wind und Sonne, dann Kohle, zuletzt Gas. Das teuerste noch benötigte Kraftwerk setzt den Preis für alle.",
    example: "2022 trieb das teure Gas so auch den Preis für Wind- und Solarstrom hoch – Grund für die Debatte über Übergewinne und Strompreisreformen." },
  { id: "vma-140", cat: "vwl", topic: "Energie & Industrie", type: "truefalse", emoji: "🧪", level: 2,
    q: "Die Produktion der energieintensiven Industrie in Deutschland liegt seit 2022 deutlich unter dem Vorkrisenniveau.",
    answer: true,
    explain: "Chemie, Metall, Glas und Papier produzierten zeitweise rund ein Fünftel weniger als 2021. Ein Teil ist strukturell: Energie bleibt in Deutschland teurer als in den USA oder China, Investitionen fließen dorthin – Debatte über „Deindustrialisierung“." },
  { id: "vma-141", cat: "vwl", topic: "Energie & Industrie", type: "quiz", emoji: "⚡", level: 2,
    q: "Warum traf der Energiepreisschock 2022 Deutschland härter als etwa Frankreich?",
    options: ["Deutschland hat kaum Dienstleistungen", "Frankreich importiert gar keine Energie", "Hoher Industrieanteil mit energieintensiven Branchen und große Abhängigkeit von russischem Gas", "Frankreich hat eine andere Währung"],
    answer: 2,
    explain: "Deutschland setzte jahrzehntelang auf billiges Pipelinegas als Standortvorteil, vor allem für die Chemie. Frankreich erzeugt seinen Strom überwiegend mit Atomkraft und hat einen kleineren Industrieanteil." },

  // ───────── Ungleichheit ─────────
  { id: "vma-142", cat: "vwl", topic: "Ungleichheit", type: "flashcard", emoji: "🍰", level: 1,
    term: "Gini-Koeffizient",
    def: "Maß der Ungleichverteilung von 0 (alle haben gleich viel) bis 1 (eine Person hat alles). Grundlage ist die Lorenzkurve.",
    example: "Deutschland: verfügbare Einkommen ≈ 0,29–0,30 (Stand 2024), Vermögen ≈ 0,75 und mehr – Vermögen sind weit ungleicher verteilt als Einkommen." },
  { id: "vma-143", cat: "vwl", topic: "Ungleichheit", type: "quiz", emoji: "🔄", level: 2,
    q: "Was senkt die Einkommensungleichheit in Deutschland am stärksten?",
    options: ["Progressive Steuern und Sozialtransfers wie Renten und Kindergeld", "Exportüberschüsse", "Niedrige Leitzinsen", "Die Mindestreserve der Banken"],
    answer: 0,
    explain: "Bei den Markteinkommen ist Deutschland recht ungleich (Gini um 0,5), nach Steuern und Transfers liegt der Wert nur noch bei rund 0,3. Der Sozialstaat verteilt also stark um – vor allem über die Renten." },
  { id: "vma-144", cat: "vwl", topic: "Ungleichheit", type: "truefalse", emoji: "🏠", level: 2,
    q: "Vermögen sind in Deutschland ungleicher verteilt als in vielen anderen Euro-Ländern.",
    answer: true,
    explain: "Ein Grund: Nur knapp die Hälfte der Haushalte besitzt Wohneigentum – eine der niedrigsten Quoten im Euroraum. Zudem zählen Rentenansprüche nicht als Vermögen; sie ersetzen hierzulande aber einen Großteil privater Altersvorsorge." },

  // ───────── Strukturwandel ─────────
  { id: "vma-145", cat: "vwl", topic: "Strukturwandel", type: "fact", emoji: "🔀", level: 1,
    title: "Drei-Sektoren-Hypothese: vom Feld über die Fabrik ins Büro",
    text: "Mit wachsendem Wohlstand wandert die Beschäftigung von der Landwirtschaft (primär) zur Industrie (sekundär) und dann zu den Dienstleistungen (tertiär). In Deutschland arbeiten heute rund drei Viertel im Dienstleistungssektor, nur gut 1 % in der Landwirtschaft.",
    more: "Treiber: Produktivität in Landwirtschaft und Industrie steigt schneller, und mit höherem Einkommen fragen Menschen mehr Dienstleistungen nach (Gesundheit, Bildung, Freizeit). Jean Fourastié nannte die Dienstleistungen „die große Hoffnung des 20. Jahrhunderts“." },
  { id: "vma-146", cat: "vwl", topic: "Strukturwandel", type: "whatif", emoji: "⚒️", level: 2,
    q: "Was passiert, wenn die Leitindustrie einer Region schrumpft?",
    steps: ["Jobs in der Kernbranche fallen weg", "Zulieferer und Handel verlieren Kunden", "Junge Fachkräfte wandern ab", "Steuereinnahmen der Kommunen sinken", "Umbau dauert Jahrzehnte"],
    text: "Beispiel Ruhrgebiet: Ende der 1950er arbeiteten rund 600.000 Menschen im Steinkohlebergbau; 2018 schloss mit Prosper-Haniel die letzte Zeche. Universitäten, Logistik und Dienstleistungen ersetzten vieles – aber die Arbeitslosigkeit blieb lange überdurchschnittlich." },
  { id: "vma-147", cat: "vwl", topic: "Strukturwandel", type: "quiz", emoji: "🎻", level: 3,
    q: "Was beschreibt die „Baumolsche Kostenkrankheit“?",
    options: ["Industriegüter werden ständig teurer als Dienstleistungen", "Medikamente werden immer billiger", "Arbeitslose kosten den Staat mehr als Beschäftigte", "Löhne in produktivitätsschwachen Diensten (Pflege, Bildung, Konzerte) steigen mit, deren Preise daher überproportional"],
    answer: 3,
    explain: "Ein Streichquartett braucht heute so viele Musiker wie 1800, muss sie aber marktüblich bezahlen. Deshalb verteuern sich Pflege, Bildung und Handwerk relativ zu Fernsehern – und ihr Anteil an BIP und Staatsausgaben wächst." },
  { id: "vma-148", cat: "vwl", topic: "Strukturwandel", type: "whatif", emoji: "🔋", level: 3,
    q: "Was passiert, wenn die Autoindustrie vom Verbrenner zum E-Auto wechselt?",
    steps: ["E-Antrieb braucht weniger Teile und Arbeit", "Zulieferer für Motor und Getriebe verlieren", "Batterie und Software werden entscheidend", "Neue Konkurrenz aus China und den USA", "Jobs und Regionen geraten unter Druck"],
    text: "Ein Verbrennungsmotor hat deutlich mehr bewegliche Teile als ein Elektromotor. Die Wertschöpfung verschiebt sich zur Batteriezelle und Software – Felder, in denen deutsche Hersteller nicht führend sind. Ein Grund für Stellenabbau bei Zulieferern seit 2023." },
  { id: "vma-149", cat: "vwl", topic: "EZB", type: "order", emoji: "🪜", level: 2,
    q: "Sortiere die Zinspolitik der EZB chronologisch.",
    items: ["Erstmals negativer Einlagesatz (2014)", "Tiefpunkt bei −0,5 % (2019)", "Zinswende mit +0,5 Punkten (Juli 2022)", "Einlagesatz-Hoch von 4,0 % (Sept. 2023)", "Erste Zinssenkung (Juni 2024)"],
    explain: "Nach acht Jahren Negativzins folgte die schnellste Straffung der EZB-Geschichte – ausgelöst durch die Inflationswelle 2021/22. Sobald die Inflation Richtung 2 % sank, lockerte die EZB wieder." },
  { id: "vma-150", cat: "vwl", topic: "Inflation", type: "order", emoji: "🔗", level: 2,
    q: "Sortiere die Inflationswelle 2021–2024 in Deutschland.",
    items: ["Corona-Lieferengpässe und Nachholkonsum", "Russlands Angriff, Energiepreisschock", "Inflation erreicht fast 9 % (Herbst 2022)", "EZB erhöht die Zinsen kräftig", "Inflation sinkt auf gut 2 % (2024)"],
    explain: "Erst Angebotsengpässe plus Nachfrage, dann der Energieschock als Brandbeschleuniger. Die Zinswende wirkte mit Verzögerung; zusätzlich fielen die Energiepreise wieder – beides drückte die Rate 2024 zurück Richtung Ziel." },
);
